def removeDuplicates(nums: list[int]) -> int:
    if not nums:
        return 0

    i = 1
    count = 1
    while i < len(nums):
        if nums[i] == nums[i - 1]:
            count += 1
            if count > 2:
                nums.pop(i)
                count -= 1
                continue
        else:
            count = 1
        i += 1

    return len(nums)

