int removeDuplicates(vector<int>& nums) {
    if (nums.empty()) return 0;

    int i = 1, count = 1;
    while (i < static_cast<int>(nums.size())) {
        if (nums[i] == nums[i - 1]) {
            ++count;
            if (count > 2) {
                nums.erase(nums.begin() + i);
                --count;
                continue;
            }
        } else {
            count = 1;
        }
        ++i;
    }

    return static_cast<int>(nums.size());
}

