int removeDuplicates(vector<int>& nums) {
    int stackSize = 2;
    for (int i = 2; i < static_cast<int>(nums.size()); ++i) {
        // 与有效前缀倒数第二个值比较，防止写入第三次。
        if (nums[i] != nums[stackSize - 2]) {
            nums[stackSize++] = nums[i];
        }
    }
    return min(stackSize, static_cast<int>(nums.size()));
}
